const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// -----------------------------------------------------------------------------
// A ciliated epithelium seen across the surface: a carpet of cilia rooted in
// basal bodies, all beating. Each cilium runs the asymmetric ciliary stroke -- a
// fast straight effective sweep, then a slow curled recovery -- and neighbours
// are held slightly out of phase, so a METACHRONAL WAVE travels across the whole
// carpet like wind over a field. The wave vector slowly rotates and a slow drift
// is mixed in so it never re-phases at any interval. The plane recedes toward a
// hazed horizon, hairs shrinking and dimming with depth, rooted in a warm mucosal
// surface. Offered as glowing dark-field, Nomarski DIC relief, tubulin
// fluorescence, or a sumi ink 'grass in the wind'.
// -----------------------------------------------------------------------------

const u = Math.min(width, height);
const sp = 0.25 + P.speed * 0.9;

const sd = (P.seed | 0);
const fr = i => { const s = Math.sin(i * 127.1 + sd * 311.7 + 5.3) * 43758.5453; return s - Math.floor(s); };

const cols = Math.round(16 + P.density * 24);
const rows = Math.max(6, Math.round(cols * 0.6));
if (!S.jit || S.seedUsed !== P.seed || S.cols !== cols || S.rows !== rows) {
  S.seedUsed = P.seed; S.cols = cols; S.rows = rows;
  S.jit = [];
  for (let j = 0; j < rows; j++) for (let i = 0; i < cols; i++) { const k = j * cols + i; S.jit.push({ jx: (fr(k * 3 + 1) - 0.5) * 0.7, jy: (fr(k * 5 + 2) - 0.5) * 0.4, ll: 0.85 + fr(k * 7 + 3) * 0.4, hj: (fr(k * 11 + 4) - 0.5) * 22, ph: fr(k * 13 + 5) * 0.5 }); }
}

const t = K.t;
const style = P.style;
const glow = 0.4 + P.energy * 1.3 + A.rms * 0.35;
const beatAmp = 0.5 + P.energy * 0.7;
const waves = 1.2 + P.coord * 3.2;
const waveAng = 0.3 + 0.5 * Math.sin(t * 0.05 * sp) + 0.2 * Math.sin(t * 0.017 * sp);
const kx = Math.cos(waveAng) * waves, ky = Math.sin(waveAng) * waves * 0.6;
const beatW = (1.4 + P.speed * 2.2);
const slowDrift = 0.35 * Math.sin(t * 0.19) + 0.22 * Math.sin(t * 0.41 + 1.0);

