if (style === 'dic') { bgH = 34; bgS = 10; bgTop = 30; bgBot = 58; mode = 'dic'; }
else if (style === 'fluor') { bgH = 300; bgS = 55; bgTop = 5; bgBot = 16; mode = 'fluor'; }
else if (style === 'ink') { bgH = 40; bgS = 16; bgTop = 52; bgBot = 72; mode = 'ink'; }
else { bgH = 195; bgS = 55; bgTop = 6; bgBot = 20; mode = 'darkfield'; }
const pale = (mode === 'dic' || mode === 'ink');

const yTop = height * 0.1;
