function litHair(colN, rowN, s, phase, jx) {
  // returns nothing; draws one cilium at current phase
  // asymmetric stroke: fast forward (effective), slow curl back (recovery)
  const e = Math.sin(phase);
  const curl = 0.5 * Math.sin(phase * 2 + 0.7);
  const lean = beatAmp * (e >= 0 ? e : e * 0.6);     // slower on the return
  const rootX = (width * 0.5 + (colN - 0.5) * width * (0.92 + rowN * 0.22)) + jx * (width / cols);
