    noFill(); stroke(hue, sat, b, a); strokeWeight(Math.max(0.5, H.L * 0.07 * depthB));
    beginShape();
    vertex(H.rootX, H.rootY);
    const qx = (H.rootX + H.midX) * 0.5, qy = (H.rootY + H.midY) * 0.5;
    vertex(qx, qy); vertex(H.midX, H.midY);
    const q2x = (H.midX + H.tipX) * 0.5, q2y = (H.midY + H.tipY) * 0.5;
    vertex(q2x, q2y); vertex(H.tipX, H.tipY);
    endShape();
