if (mode === 'darkfield' || mode === 'fluor') blendMode(BLEND);

// hazed horizon glow to seal the top
noStroke(); for (let b = 0; b < 6; b++) { fill(bgH, bgS * 0.5, pale ? bgTop + 8 : 22, 12); rect(0, yTop - u * 0.02 * b, width, u * 0.05); }
